//! Compact storage for the connection's infrequently consumed ChaCha stream.
use chacha20::ChaCha12Rng;
use core::convert::Infallible;
use rand::{SeedableRng, TryCryptoRng, TryRng};

pub(super) struct CompactRng {
    seed: [u8; 32],
    word_pos: u128,
}

impl CompactRng {
    pub(super) fn from_generator(rng: &ChaCha12Rng) -> Self {
        // Connections only use the default stream. Keep the initial constructor
        // buffered while it consumes several values, then discard its cache.
        debug_assert_eq!(rng.get_stream(), 0);
        Self {
            seed: rng.get_seed(),
            word_pos: rng.get_word_pos(),
        }
    }

    fn with_generator<T>(&mut self, f: impl FnOnce(&mut ChaCha12Rng) -> T) -> T {
        let mut rng = ChaCha12Rng::from_seed(self.seed);
        rng.set_word_pos(self.word_pos);
        let result = f(&mut rng);
        self.word_pos = rng.get_word_pos();
        result
    }
}

impl TryRng for CompactRng {
    type Error = Infallible;
    fn try_next_u32(&mut self) -> Result<u32, Infallible> {
        self.with_generator(|rng| rng.try_next_u32())
    }
    fn try_next_u64(&mut self) -> Result<u64, Infallible> {
        self.with_generator(|rng| rng.try_next_u64())
    }
    fn try_fill_bytes(&mut self, dst: &mut [u8]) -> Result<(), Infallible> {
        self.with_generator(|rng| rng.try_fill_bytes(dst))
    }
}
impl TryCryptoRng for CompactRng {}

#[cfg(test)]
mod tests {
    use super::*;
    use rand::{rngs::StdRng, Rng};

    #[test]
    fn mixed_calls_match_pinned_standard_generator() {
        for seed in [[0; 32], [1; 32], [255; 32]] {
            for prefix in [0, 1, 15, 16, 63, 64, 65, 127] {
                let mut reference = StdRng::from_seed(seed);
                let mut buffered = ChaCha12Rng::from_seed(seed);
                let mut a = vec![0; prefix];
                let mut b = vec![0; prefix];
                reference.fill_bytes(&mut a);
                buffered.fill_bytes(&mut b);
                assert_eq!(a, b);
                let mut compact = CompactRng::from_generator(&buffered);
                for len in [0, 1, 2, 3, 4, 7, 8, 15, 16, 63, 64, 65, 255, 256, 257] {
                    assert_eq!(reference.next_u32(), compact.next_u32());
                    assert_eq!(reference.next_u64(), compact.next_u64());
                    let mut a = vec![0; len];
                    let mut b = vec![0; len];
                    reference.fill_bytes(&mut a);
                    compact.fill_bytes(&mut b);
                    assert_eq!(a, b);
                }
            }
        }
        assert!(size_of::<CompactRng>() < size_of::<StdRng>());
    }
}

